import numpy as np
import matplotlib.pyplot as plt
import matplotlib.ticker as ticker
from statsmodels.distributions.empirical_distribution import ECDF

LEGEND_SIZE = 16
LABEL_SIZE = 14
TICK_SIZE = 16
SMALL_SIZE = 19
MEDIUM_SIZE = 27
BIGGER_SIZE = 33

plt.rcParams.update({
    'axes.titlesize': SMALL_SIZE,
    'axes.labelsize': LABEL_SIZE,
    'xtick.labelsize': TICK_SIZE,
    'ytick.labelsize': TICK_SIZE,
    'legend.fontsize': LEGEND_SIZE,
    'figure.titlesize': MEDIUM_SIZE,
})

def set_plot_rc(font_size=10):
    plt.rcParams.update({
        'font.size': font_size + 20,
        'axes.titlesize': font_size + 20,
        'axes.labelsize': font_size + 20,
        'xtick.labelsize': font_size + 10,
        'ytick.labelsize': font_size + 10,
        'legend.fontsize': font_size + 17,
        'figure.titlesize': font_size + 20
    })

def plot_cdf_n_curves(list_curve, colors, styles, labels, x_label, chart_path, log_scale=True, linewidth=3, base=False):
    set_plot_rc()
    plt.rcParams.update({'font.family': 'sans-serif'})

    fig, ax = plt.subplots(figsize=(16, 14))

    ecdf_list = [ECDF(curve) for curve in list_curve]

    for i, (curve, color, style, label) in enumerate(zip(list_curve, colors, styles, labels)):
        ax.plot(ecdf_list[i].x, ecdf_list[i].y, linestyle=style, color=color, label=label, linewidth=linewidth)

    if len(labels) > 1:
        ax.legend(loc='lower right')

    if log_scale:
        ax.set_xscale('symlog')
        ax.xaxis.set_major_formatter(ticker.FuncFormatter(lambda x, p: format(int(x), ',').replace(',', ' ')))

    ax.set_xlabel(x_label)
    ax.set_adjustable("box")
    ax.set_ylabel('CDF')
    ax.grid(visible=True, which='major', linestyle='-')
    plt.tight_layout()

    plt.savefig(f"{chart_path}.pdf", pad_inches=0)
    #plt.savefig(f"{chart_path}.png", pad_inches=0)
    plt.clf()
    plt.cla()
    plt.close('all')


